<!doctype html>

<!-- Intro overlay -->
<div id="introOverlay">
  <div class="intro-card">
    <div class="medallion"></div>
    <div class="logo-text">MEDALLION&nbsp;MAZE</div>
    <div class="welcome">WELCOME</div>
  </div>
</div>

<html lang="en">
<head>
  <script id="stripe-config">window.STRIPE_CHECKOUT_URL="https://buy.stripe.com/00w5kEbOVcBX66M9SK8Vi00";</script>

<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>Arc Angels™ · Medallion Maze</title>
<meta name="theme-color" content="#0f0e0c"/>
<style>
:root{
  --paper:#0F0E0C; --ink:#EDE7D8; --muted:#C9C3BB;
  --gold1:#F7EACC; --gold2:#E7CF97; --gold3:#C9A760; --gold4:#A4813C;
  --panelBg:linear-gradient(180deg,#171410ee,#171410cc);
  --panelBorder:#3a3026;
  --btnText:#2e2212; --btnFace:linear-gradient(180deg,var(--gold1),var(--gold2) 55%,var(--gold3));
  --hueDeg:0; --sat:112%;
}
body.day{
  --paper:#F7F3EA; --ink:#1A140D; --muted:#584D40;
  --panelBg:linear-gradient(180deg,#fffefaee,#f1eaddcc);
  --panelBorder:#D7CBB5; --btnText:#2a210f; --btnFace:linear-gradient(180deg,#ffffff,#f6e7c8 60%,#e3cc93);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;filter:hue-rotate(calc(var(--hueDeg)*1deg)) saturate(var(--sat));transition:background .6s,color .6s}

/* maze background + stars */
.maze-bg{position:fixed;inset:0;z-index:0;pointer-events:none;opacity:.9;
  background:
    repeating-radial-gradient(circle at 50% 40%, rgba(255,238,210,.08) 0 2px, #0000 2px 28px),
    repeating-conic-gradient(from -90deg, rgba(255,238,210,.05) 0 10deg, #0000 10deg 20deg);
  mask-image: radial-gradient(circle at 50% 46%, #0000 0 34%, #000 35%);
}
body.day .maze-bg{opacity:.75}
#stars{position:fixed;inset:0;z-index:1;pointer-events:none;opacity:.25}

/* header */
header{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px clamp(16px,4vw,40px);position:relative;z-index:3}
.brand{display:flex;align-items:center;gap:.75rem}
.brandName{font-weight:900;letter-spacing:.24em;text-transform:uppercase;font-variant:small-caps;
  font-family:ui-serif,Georgia,Times,serif;font-size:clamp(1.1rem,2.6vw,1.6rem);
  background:linear-gradient(180deg,#fff,#e7d8b9 60%,#8a6b35);
  -webkit-background-clip:text;background-clip:text;color:transparent;
  text-shadow:0 1px 0 #fff6, 0 8px 28px rgba(201,167,96,.28)}
body.day .brandName{background:none;color:#2a2215;text-shadow:0 1px 0 #fff, 0 1px 16px rgba(0,0,0,.05)}
.seal{width:48px;aspect-ratio:1;border-radius:50%;background:
  radial-gradient(120% 120% at 20% 15%,#ffffffaa 0,#fff0 40%),
  radial-gradient(140% 140% at 85% 85%,#00000033 0,#0000 40%),
  conic-gradient(from 210deg,#caa45d,#a9803e,#e7cf97,#caa45d);
  display:grid;place-items:center;box-shadow:inset 0 2px 8px #ffffffaa, inset 0 -10px 20px rgba(90,60,20,.28), 0 12px 28px rgba(0,0,0,.35), 0 0 0 1px #ffffff26}
.seal::after{content:"MM";font-weight:1000;color:#3a2b12;text-shadow:0 1px 0 #fff8, 0 2px 8px #0006}

.controls button{border:0;border-radius:999px;padding:.62rem 1rem;background:#1d1915;color:#eadfcb;border:1px solid var(--panelBorder);cursor:pointer;font-weight:850}
.controls .primary{background:var(--btnFace);color:var(--btnText);border:0;box-shadow:0 10px 22px rgba(201,167,96,.35),inset 0 0 0 1px #ffffffe6}

/* hero */
.hero{text-align:center;padding:clamp(30px,6vw,90px)}
.hero h1{font-family:ui-serif,Georgia,Times,serif;font-weight:1000;line-height:1.02;font-size:clamp(2.8rem,6vw,5.2rem);margin:7vh 0 .6rem}
.sub{max-width:min(980px,92vw);margin:0 auto 1rem;color:var(--muted);font-size:clamp(1.05rem,1.9vw,1.3rem)}

/* medallion cluster + creative effects */
.cluster{position:relative;width:min(900px,92vw);aspect-ratio:1;margin:28px auto 8px;perspective:1600px;filter:drop-shadow(0 50px 120px rgba(201,167,96,.45))}
.parallax{position:absolute;inset:0;transform-style:preserve-3d;transition:transform .8s cubic-bezier(.22,.61,.36,1)}
.halo{position:absolute;inset:-12%;transform:translateZ(40px);
  background:radial-gradient(50% 40% at 50% 46%,rgba(255,230,180,.95),#0000 70%);filter:blur(44px);opacity:.95;animation:halo 9s ease-in-out infinite}
@keyframes halo{0%,100%{opacity:.9}50%{opacity:1}}
.rim .outer{position:absolute;inset:0;border-radius:50%;
  background:radial-gradient(circle at 50% 35%,#fff 0 36%,#f7ebcf 50%,#e7cf97 62%,#c9a760 78%,#a4813c 92%,#0000 96%);
  -webkit-mask: radial-gradient(circle at 50% 52%,#000 72%,#0000 73%), radial-gradient(circle at 50% 50%,#0000 82%,#000 83%);
          mask: radial-gradient(circle at 50% 52%,#000 72%,#0000 73%), radial-gradient(circle at 50% 50%,#0000 82%,#000 83%);
  box-shadow:inset 0 0 2px #fff,inset 0 22px 50px rgba(255,255,255,.38),0 30px 80px rgba(161,126,60,.45)}
.face{position:absolute;inset:9%;border-radius:50%;transform:translateZ(80px);
  background:radial-gradient(circle at 50% 40%,#fff 0 40%,#f6e6c8 58%,#e5c98e 78%,#c7a35f 88%,#a6803e 96%),repeating-conic-gradient(from 0deg,rgba(168,130,62,.18) 0 8deg,#0000 8deg 16deg);
  box-shadow:inset 0 3px 12px rgba(255,255,255,.55),inset 0 -12px 28px rgba(166,128,58,.28)}
.engraved-img{position:absolute;inset:12%;border-radius:50%;overflow:hidden;transform:translateZ(160px);box-shadow:inset 0 0 0 2px #ffffffa8, 0 0 0 1px #00000022}
.engraved-img img{width:100%;height:100%;object-fit:cover;filter:contrast(1.02) brightness(1.0) saturate(1.02)}
.progress{position:absolute;inset:3%;border-radius:50%;background:conic-gradient(from -90deg,rgba(201,167,96,0) var(--pct,0%),rgba(201,167,96,.5) var(--pct,0%));mask:radial-gradient(circle,#0000 70%,#000 71%);transform:translateZ(140px)}

/* creative medal effects */
.orbit{position:absolute;inset:-6%;border-radius:50%;transform:translateZ(200px);
  background:radial-gradient(2px 2px at 50% 6%, rgba(255,240,200,.85), transparent 60%),
             radial-gradient(2px 2px at 94% 50%, rgba(255,240,200,.85), transparent 60%),
             radial-gradient(2px 2px at 50% 94%, rgba(255,240,200,.85), transparent 60%),
             radial-gradient(2px 2px at 6% 50%, rgba(255,240,200,.85), transparent 60%);
  animation:orbitSpin 10s linear infinite; opacity:.65; mix-blend-mode:screen; pointer-events:none}
@keyframes orbitSpin{to{transform:translateZ(200px) rotate(360deg)}}
.runes{position:absolute;inset:-2%;border-radius:50%; transform:translateZ(180px);
  background: repeating-conic-gradient(from 0deg, rgba(255,230,180,.18) 0 12deg, rgba(255,230,180,0) 12deg 24deg);
  -webkit-mask: radial-gradient(circle at 50% 50%, transparent 77%, black 79%, black 83%, transparent 85%);
          mask: radial-gradient(circle at 50% 50%, transparent 77%, black 79%, black 83%, transparent 85%);
  animation:runesSweep 18s linear infinite; pointer-events:none; opacity:.6; mix-blend-mode:screen; filter:blur(.6px)}
@keyframes runesSweep{to{transform:translateZ(180px) rotate(-360deg)}}
.sheen-medal{position:absolute;inset:6%;border-radius:50%; transform:translateZ(200px);
  background:linear-gradient(115deg, rgba(255,255,255,0) 40%, rgba(255,255,255,.22) 50%, rgba(255,255,255,0) 60%);
  mix-blend-mode:screen; pointer-events:none; animation:medalShine 4.5s ease-in-out infinite}
@keyframes medalShine{0%,100%{transform:translateZ(200px) translateX(-6%) rotate(6deg)}50%{transform:translateZ(200px) translateX(6%) rotate(6deg)}}

/* cta */
.cta button{border:0;border-radius:999px;padding:1.12rem 1.75rem;background:var(--btnFace);color:var(--btnText);font-weight:1000;letter-spacing:.06em;font-size:clamp(1.05rem,1.9vw,1.2rem);box-shadow:0 16px 36px rgba(201,167,96,.45),inset 0 0 0 1px #ffffffe6;cursor:pointer;position:relative;overflow:hidden}
.cta button::after{content:"";position:absolute;inset:0;opacity:.45;background:linear-gradient(100deg,#fff0 0%,#fff 16%,#fff0 32%);transform:translateX(-120%);animation:shimmer 2.6s ease-in-out infinite}
@keyframes shimmer{to{transform:translateX(120%)}}

/* The Call panel */
.call{display:grid;place-items:center;margin:48px 0}
.panel{width:min(1020px,92vw);border-radius:28px;background:var(--panelBg);border:1px solid var(--panelBorder);padding:clamp(22px,4.5vw,44px);box-shadow:0 36px 90px rgba(0,0,0,.35);backdrop-filter:blur(8px);text-align:center}
.panel h2{font-family:ui-serif,Georgia,Times,serif;font-size:clamp(2rem,3vw,2.6rem);margin:.3rem auto .6rem}
.panel p{color:var(--muted);max-width:70ch;margin:0 auto 10px;}
.meter{--p:19;margin:22px auto 0;width:min(620px,90%);height:16px;border-radius:999px;background:#2a241d;position:relative;overflow:hidden;outline:1px solid var(--panelBorder)}
body.day .meter{background:#e8e0cf}
.meter::before{content:"";position:absolute;inset:0;width:calc(var(--p)*1%);background:linear-gradient(90deg,#EAD7B1,#D1AF66);border-radius:999px;box-shadow:inset 0 0 24px 8px rgba(201,167,96,.28)}
.meter-label{font-size:1.02rem;color:var(--muted);margin-top:.6rem;text-align:center}

/* modal */
.modal{position:fixed;inset:0;display:none;place-items:center;z-index:20000;background:radial-gradient(70% 70% at 50% 50%,rgba(22,19,15,.92),rgba(14,12,10,.7));backdrop-filter:blur(8px)}
body.day .modal{background:radial-gradient(70% 70% at 50% 50%,rgba(255,255,255,.92),rgba(230,224,210,.6))}
.modal.open{display:grid}
.card{width:min(980px,94vw);border-radius:24px;padding:clamp(20px,3.2vw,34px);background:linear-gradient(180deg,#1a1713,#16130f);border:1px solid var(--panelBorder);box-shadow:0 50px 120px rgba(0,0,0,.55);position:relative;overflow:hidden}
body.day .card{background:linear-gradient(180deg,#fffdfa,#f0e6d8)}
.card .closeX{position:absolute;top:10px;right:12px;width:40px;height:40px;border-radius:10px;border:1px solid var(--panelBorder);background:rgba(0,0,0,.25);color:#f6e7c8;display:grid;place-items:center;cursor:pointer;font-weight:900}
body.day .card .closeX{background:rgba(255,255,255,.7);color:#2a2215}
.steps{display:flex;gap:10px;margin-bottom:12px;justify-content:center}
.dot{width:10px;height:10px;border-radius:50%;background:#3a3026} .dot.active{background:#D1AF66}
.grid{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(200px,1fr))}
label{font-size:.95rem;color:#d2c8b6} body.day label{color:#5b4e40}
input,textarea,select{width:100%;padding:1rem;border-radius:12px;border:1px solid var(--panelBorder);background:#1f1a14;color:#ede7d8;box-shadow:inset 0 0 0 1px #00000020}
body.day input, body.day textarea, body.day select{background:#fffdf6;color:#2a2215;border-color:#d7cbb5;box-shadow:none}
textarea{min-height:120px}
.actions{display:flex;justify-content:space-between;gap:10px;margin-top:12px;align-items:center}
.btn{border:0;padding:1rem 1.25rem;border-radius:14px;font-weight:900;cursor:pointer;letter-spacing:.04em}
.btn.primary{background:linear-gradient(180deg,var(--gold2),var(--gold3));color:#1f160a;box-shadow:0 8px 20px rgba(201,167,96,.35),inset 0 0 0 1px #ffffffe6}
.btn.ghost{background:transparent;color:var(--ink);border:1px solid var(--panelBorder)}
.btn.done{background:linear-gradient(180deg,#c6f4df,#7adac0); color:#0f2a23; box-shadow:0 8px 24px rgba(122,218,192,.35), inset 0 0 0 1px #ffffffcc}

/* frame + 3D id card */
.frame{margin:24px auto;width:min(860px,96vw);aspect-ratio:auto;min-height:360px;border-radius:28px;background:
  radial-gradient(120% 120% at 90% 10%,#ffffff22,#0000 35%),
  radial-gradient(90% 90% at 10% 10%,#000 0,#1b1712 50%,#0f0d0a 100%);
  box-shadow:0 60px 140px rgba(0,0,0,.35),inset 0 0 0 1px rgba(255,255,255,.06);padding:24px;display:grid;place-items:center;position:relative;overflow:hidden}
body.day .frame{background:radial-gradient(120% 120% at 90% 10%,#00000011,#0000 35%),radial-gradient(90% 90% at 10% 10%,#fff 0,#efe6d5 60%,#eadfc9 100%)}
#confetti{position:absolute;inset:0;pointer-events:none}

.idCard3D{position:relative;width:min(860px,92%);height:clamp(300px,46vh,560px);margin:auto;transform-style:preserve-3d;perspective:1200px}
.idCard3D.flip .front{transform:rotateY(180deg)}
.idCard3D.flip .back{transform:rotateY(0deg)}
.idCard{position:absolute;inset:0;border-radius:22px;overflow:hidden;box-shadow:0 24px 60px rgba(0,0,0,.45),inset 0 0 0 1px #ffffff5a;transform-style:preserve-3d}
.idCard.face{transition:transform .9s cubic-bezier(.2,.7,.2,1);backface-visibility:hidden}
.front{background:linear-gradient(180deg,#f6e7c8,#e7cf97 40%,#c9a760 72%,#a4813c 100%);transform:rotateY(0deg)}
.back{background:linear-gradient(180deg,#dac8a0,#b99854);transform:rotateY(180deg)}
/* Angels art overlay */
.idCard .bg.angels{position:absolute;inset:0;background-image:url('data:image/jpeg;base64,